            try:
                if data.startswith(b"\x1f\x1e"):
                    name = "z: Pack"
                elif data.startswith(b"\x1f\xa0") and len(data) >= 4:
                    name = "SCO Compress LZH"
                elif data.startswith(b"BZh") and len(data) >= 4 and data[3:4] in b"123456789":
                    name = "bz2: bzip2"
                else:
                    name, _ = decode(data)
                print(f"Compression of {path} is {name}")
            except Exception:
                print(f"Unknown or invalid compression format in file {path}")
        return rc
    if cmd in ("verify", "v"):
        if len(argv) != 3:
            print(VERSION)
            return 255
        packed, expected = argv[1:]
        try:
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            reference = open(expected, "rb").read()
        except OSError:
            return fail("Could not read file " + expected)
        try:
            _, result = decode(src)
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        if len(result) != len(reference):
            return fail(f"Verify failed for {packed} and {expected} - sizes differ")
        if result != reference:
            index = next(i for i, (a, b) in enumerate(zip(result, reference)) if a != b)
            return fail(f"Verify failed for {packed} and {expected} - contents differ @ {index}")
        print("Files match!")
        return 0
    if cmd in ("decompress", "d"):
        if len(argv) != 3:
            print(VERSION)
            return 255
        packed, output = argv[1:]
        try:
            st = os.stat(packed)
            src = open(packed, "rb").read()
        except OSError:
            return fail("Could not read file " + packed)
        try:
            _, result = decode(src)
        except Exception:
            return fail(f"Unknown or invalid compression format in file {packed}")
        try:
            with open(output, "wb") as f:
                f.write(result)
            if preserve:
                os.utime(output, (st.st_atime, st.st_mtime))
        except OSError:
            print("Could not write file " + output)
        return 0
    print("Unknown command")
    print(VERSION)
    return 255


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"}

